// Public semantic-color values, explicitly resolved against each appearance.
#import <UIKit/UIKit.h>
int main(){@autoreleasepool{NSMutableDictionary *out=[NSMutableDictionary new];for(NSNumber *dark in @[@NO,@YES]){UITraitCollection *t=[UITraitCollection traitCollectionWithUserInterfaceStyle:dark.boolValue?UIUserInterfaceStyleDark:UIUserInterfaceStyleLight];NSArray *colors=@[UIColor.systemBlueColor,UIColor.systemRedColor,UIColor.systemGreenColor,UIColor.systemOrangeColor,UIColor.systemPurpleColor,UIColor.systemMintColor,UIColor.systemYellowColor,UIColor.systemIndigoColor,UIColor.systemGrayColor,UIColor.systemTealColor,UIColor.systemCyanColor,UIColor.systemPinkColor];NSMutableArray *rows=[NSMutableArray new];for(UIColor *color in colors){CGFloat r,g,b,a;[[color resolvedColorWithTraitCollection:t] getRed:&r green:&g blue:&b alpha:&a];[rows addObject:@[@(r*255),@(g*255),@(b*255),@(a)]];}out[dark.boolValue?@"dark":@"light"]=rows;}out[@"os"]=NSProcessInfo.processInfo.operatingSystemVersionString;NSData *data=[NSJSONSerialization dataWithJSONObject:out options:NSJSONWritingPrettyPrinted error:nil];puts([[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding].UTF8String);}return 0;}
